static const char *const GE_LOCALE_CODES[] = {"en","de","es","fr","nl","it","tr","ru","pt","el"};
static const char *const GE_TEMPLATE_NAMES[] = {"accountActivation","accountMultiRegistration","addedContributionMessage","assistedRegistrationConfirm","contributionChangedByModerator","contributionConfirmed","contributionDeleted","contributionDenied","customEmail","emailChangeConfirm","emailChangeDone","emailChangeNotice","emailChangeSupport","resetPassword","thankYouCardPaid","transactionLinkRedeemed","transactionReceived"};

const char *ge_locale_code(ge_locale_t l)     { return GE_LOCALE_CODES[l]; }
const char *ge_template_name(ge_template_t t) { return GE_TEMPLATE_NAMES[t]; }

int ge_template_by_name(const char *name) {
    for (int i = 0; i < GE_TPL_COUNT; i++)
        if (strcmp(GE_TEMPLATE_NAMES[i], name) == 0) return i;
    return -1;
}
int ge_locale_by_code(const char *code) {
    for (int i = 0; i < GE_LOCALE_COUNT; i++)
        if (strcmp(GE_LOCALE_CODES[i], code) == 0) return i;
    return -1;
}

/* Internal, as the trailing underscore says -- the per-template wrappers below
 * are the API.
 * prog = GE_PROGS[base + (locale * n_combos + combo) * 2 + kind], kind 0=html 1=subject */
int ge_emit_(uint32_t base, uint32_t n_combos, ge_locale_t locale, uint32_t combo,
             const char *const *sv, ge_mail_t *out) {
    if ((unsigned)locale >= GE_LOCALE_COUNT) return -1;
    const ge_prog_t *p = &GE_PROGS[base + ((uint32_t)locale * n_combos + combo) * 2];
    if (ge_run(GE_POOL, &GE_OPS[p[0].start], p[0].count, sv, &out->html) != 0) return -1;
    if (ge_run(GE_POOL, &GE_OPS[p[1].start], p[1].count, sv, &out->subject) != 0) {
        ge_str_free(&out->html);
        return -1;
    }
    return 0;
}

/* Same into an arena: no malloc, no free. Both documents sit back to back in
 * the same buffer. */
int ge_emit_into_(uint32_t base, uint32_t n_combos, ge_locale_t locale, uint32_t combo,
                  const char *const *sv, ge_arena_t *a, ge_mail_t *out) {
    if ((unsigned)locale >= GE_LOCALE_COUNT) return -1;
    const ge_prog_t *p = &GE_PROGS[base + ((uint32_t)locale * n_combos + combo) * 2];
    /* On -1, out->html.len carries the total requirement for ge_arena_ensure(). */
    if (ge_run_into(GE_POOL, &GE_OPS[p[0].start], p[0].count, sv, a, &out->html) != 0) return -1;
    if (ge_run_into(GE_POOL, &GE_OPS[p[1].start], p[1].count, sv, a, &out->subject) != 0) {
        size_t need = a->used + out->subject.len;
        out->html.data = NULL;
        out->html.len  = need;
        return -1;
    }
    return 0;
}

int ge_emit_into_fast_(uint32_t base, uint32_t n_combos, ge_locale_t locale, uint32_t combo,
                       const char *const *sv, ge_arena_t *a, ge_mail_t *out) {
    const ge_prog_t *p = &GE_PROGS[base + ((uint32_t)locale * n_combos + combo) * 2];
    ge_run_into_fast(GE_POOL, &GE_OPS[p[0].start], p[0].count, sv, a, &out->html);
    ge_run_into_fast(GE_POOL, &GE_OPS[p[1].start], p[1].count, sv, a, &out->subject);
    return 0;
}

static void ge_prep_account_activation(ge_locale_t locale, const ge_account_activation_t *v, const char **sv, uint32_t *combo) {
    sv[0] = ge_locale_code(locale);
    sv[1] = v->activation_link;
    sv[2] = v->first_name;
    sv[3] = v->hours;
    sv[4] = v->last_name;
    sv[5] = v->logo_url;
    sv[6] = v->minutes;
    sv[7] = v->resend_link;
    uint32_t k = 0;
    k = k * 2u + ((GE_HAS(v->logo_url)) ? 0u : 1u);   /* logo */
    k = k * 2u + ((GE_HAS(v->minutes)) ? 0u : 1u);   /* duration */
    *combo = k;
}

int ge_render_account_activation(ge_locale_t locale, const ge_account_activation_t *v, ge_mail_t *out) {
    const char *sv[8]; uint32_t combo;
    ge_prep_account_activation(locale, v, sv, &combo);
    return ge_emit_(0u, 4u, locale, combo, sv, out);
}

int ge_render_account_activation_into(ge_locale_t locale, const ge_account_activation_t *v, ge_arena_t *a, ge_mail_t *out) {
    const char *sv[8]; uint32_t combo;
    ge_prep_account_activation(locale, v, sv, &combo);
    return ge_emit_into_(0u, 4u, locale, combo, sv, a, out);
}

int ge_render_account_activation_into_fast(ge_locale_t locale, const ge_account_activation_t *v, ge_arena_t *a, ge_mail_t *out) {
    const char *sv[8]; uint32_t combo;
    ge_prep_account_activation(locale, v, sv, &combo);
    return ge_emit_into_fast_(0u, 4u, locale, combo, sv, a, out);
}

